def assign_points(points: list[list[float]], centroids: list[list[float]]) -> list[int]:

    labels: list[int] = []
    dims: int = len(centroids[0])
    for p in points:
        best: int = 0
        best_d: float = -1.0
        for c in range(len(centroids)):
            d: float = 0.0
            for t in range(dims):
                diff: float = p[t] - centroids[c][t]
                d += diff * diff
            if best_d < 0.0 or d < best_d:
                best_d = d
                best = c
        labels.append(best)
    return labels

